255	/// Run a task, returning what it prints.
256	fn run(task: &Task) -> Result<String, String> {
257	    let manifest = root().join("Cargo.toml");
258	    let read = || std::fs::read_to_string(&manifest).map_err(|e| format!("Cargo.toml: {e}"));
259	    match task {
260	        Task::Version => version_in(&read()?),
261	        Task::Bump { to } => {
262	            let bump = match to.as_str() {
263	                "next" => Bump::Next,
264	                "bare" => Bump::Bare,
265	                version => Bump::To(version.to_string()),
266	            };
267	            let text = read()?;
268	            let current = version_in(&text)?;
269	            let new = bumped(&current, &bump)?;
270	            if new == current {
271	                return Ok(format!("{current}, as it was"));
272	            }
273	            std::fs::write(&manifest, with_version(&text, &new)?)
274	                .map_err(|e| format!("Cargo.toml: {e}"))?;
275	            refresh_lock(&root())?;
276	            Ok(format!("{current} -> {new}, Cargo.lock refreshed"))
277	        }
278	        Task::Completions { names } => Ok(completion_script(names).trim_end().to_string()),
279	    }
280	}
