/// The arguments of a retired name, swallowed so its fix-it shows for
/// any invocation.
#[derive(Args, Debug)]
#[command(disable_help_flag = true)]
pub struct RetiredArgs {
    #[arg(trailing_var_arg = true, allow_hyphen_values = true, num_args = 0..)]
    pub rest: Vec<String>,
}

/// The fix-it for a retired check name, `old`, now `check <new>`.
pub fn retired_name(old: &str, new: &str) -> String {
    format!("{old}: retired at 0.85.25, now `check {new}` (same flags)")
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The fix-it names the old command and the new, flags unchanged.
    #[test]
    fn a_retired_name_names_its_check() {
        assert_eq!(
            retired_name("validate-config", "config"),
            "validate-config: retired at 0.85.25, now `check config` (same flags)"
        );
    }

    /// Each old name parses, whatever flags follow, to its retired
    /// variant, and each check by its new name.
    #[test]
    fn the_old_names_parse_to_their_refusals() {
        use crate::{Cli, Commands};
        use clap::Parser;
        let parse = |args: &[&str]| Cli::try_parse_from(args).expect("parses").command;
        for old in [
            "validate-agent",
            "validate-bot",
            "validate-desc",
            "validate-config",
            "validate-anchors",
            "validate-todo",
        ] {
            let parsed = parse(&["vc-x1", old, "-s", "b", "--bogus"]);
            let refused = matches!(
                parsed,
                Some(
                    Commands::ValidateAgentOld(_)
                        | Commands::ValidateBotOld(_)
                        | Commands::ValidateDescOld(_)
                        | Commands::ValidateConfigOld(_)
                        | Commands::ValidateAnchorsOld(_)
                        | Commands::ValidateTodoOld(_)
                )
            );
            assert!(refused, "{old}: {parsed:?}");
        }
        for (new, flags, expect) in [
            ("agent", &[][..], "Agent"),
            ("desc", &["-s", "b"][..], "Desc"),
            ("config", &[][..], "Config"),
            ("anchors", &[][..], "Anchors"),
            ("todo", &[][..], "Todo"),
        ] {
            let mut args = vec!["vc-x1", "check", new];
            args.extend(flags);
            let parsed = format!("{:?}", parse(&args));
            assert!(parsed.contains(&format!("{expect}(")), "{new}: {parsed}");
        }
    }
}

