        assert_eq!(two(json!(null), Some("a")).bin(None).unwrap().name, "a");
        assert_eq!(
            two(json!({"default-bin": "b"}), Some("a")).bin(None).unwrap().name,
            "b",
            "default-bin outranks default-run"
        );
