1	//! The `check config` subcommand: check a workspace's config
2	//! files against the schema, their own links, and the structural
3	//! key every instance config carries.
4	//!
5	//! Four checks:
6	//!
7	//! - every key is one `vc-config.md` declares for that side, and a
8	//!   `str-list` key holds an array rather than a scalar. A key the
9	//!   profile form retired is named so, with its replacement
10	//! - the legacy `[workspace]` schema is rejected with a fix-it, and
11	//!   a dual workspace's two `[repos]` registries must resolve to the
12	//!   same pair
13	//! - the file's own `[[N]]` references and `#anchor` links resolve
14	//!   ([`crate::check_anchors`]), and a `vc-config.md#<anchor>`
15	//!   link names a real key section, which is a schema lookup since
16	//!   build.rs derives those anchors from key paths
17	//! - a side's config carries `repos.work`, the one `required` key
18	//!
19	//! Read-only, and exits non-zero when anything is found. Split out
20	//! of `config --validate` at 0.80.6: `config` prints the schema,
21	//! and checking a file against it is a different verb that belongs
22	//! beside `check desc`, `check todo`, `check agent`, and
23	//! `check anchors`.
24	
25	use std::collections::HashMap;
26	use std::error::Error;
27	use std::path::Path;
28	
29	use clap::Args;
30	use log::{debug, info, trace, warn};
31	
32	use crate::common::{bot_repo_path, find_workspace_root, reject_legacy_config};
33	use crate::config_cmd::{ConfigTarget, ConfigTargetArgs, in_any, in_bot_side, in_work_side};
34	use crate::config_schema::{Home, schema};
35	use crate::context::Context;
36	use crate::desc_helpers::VC_CONFIG_FILE;
37	use crate::options_flags::scope::Side;
38	use crate::subcommand::SubcommandRunner;
39	
40	/// Clap-derived args for `check config`.
41	#[derive(Args, Debug)]
42	pub struct CheckConfigArgs {
43	    /// What to check: a side's config, both by default, or a file
44	    #[command(flatten)]
45	    pub target: ConfigTargetArgs,
46	}
47	
48	/// Inputs to the check config op, flat, owned, clap-free.
49	pub struct CheckConfigParams {
50	    pub target: ConfigTarget,
51	}
52	
53	impl SubcommandRunner for CheckConfigArgs {
54	    type Params = CheckConfigParams;
55	
56	    /// Resolve the target, refusing the retired positional.
57	    fn to_params(&self) -> Result<Self::Params, String> {
58	        Ok(CheckConfigParams {
59	            target: self.target.target("check config")?,
60	        })
61	    }
62	
63	    /// Run the `check_config` op.
64	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
65	        check_config(ctx, params)
66	    }
67	}
68	
69	/// Run the `check config` subcommand.
70	///
71	/// `ctx` is unused: the check reads config files and neither the
72	/// user config nor the `--log` path applies. It is present for the
73	/// uniform subcommand-layer signature.
74	pub fn check_config(
75	    _ctx: &Context,
76	    params: &CheckConfigParams,
77	) -> Result<(), Box<dyn std::error::Error>> {
78	    debug!("check config: enter");
79	    let root = find_workspace_root();
80	    let c = validate(params, root.as_deref())?;
81	    // The counts are the summary's point: they separate a pass that
82	    // checked something from one that had nothing to check.
83	    info!(
84	        "check config: {} file(s), {} key(s) and {} link(s) checked, {} required key(s), \
85	         {} problem(s) found",
86	        c.files, c.keys, c.links, c.required, c.findings
87	    );
88	    if c.findings > 0 {
89	        debug!("check config: exit with findings");
90	        Err(format!("check config: {} problem(s) found", c.findings).into())
91	    } else {
