/// `[install]` is told nothing.
fn install_hint(repo: &Path) -> String {
    let configured = crate::config_md::load(repo)
        .ok()
        .flatten()
        .is_some_and(|cfg| {
            cfg.map
                .keys()
                .any(|k| k.starts_with("install.") || k.starts_with("build."))
        });
    match configured {
        true => " `vc-x1 install` installs the artifact".to_string(),
        false => String::new(),
    }
}

