/// CLI args for the `agent-files` group.
#[derive(Args, Debug)]
pub struct AgentFilesArgs {
    #[command(subcommand)]
    pub command: AgentFilesCommand,
}

/// The `agent-files` subcommands.
#[derive(Subcommand, Debug)]
pub enum AgentFilesCommand {
    /// Print the workspace's set version, bare, one per line
    #[command(
        long_about = "Print the workspace's agent-files set version, the name of\n\
        its agent-data/agent-files-vX.Y.Z file with the prefix\n\
        removed, one per line when a bump left several. Fails with a\n\
        message when there is none: outside a vc-x1 workspace, or in\n\
        one without the file."
    )]
    Version,

    /// Name the set files that differ between two copies of the set
    #[command(
        long_about = "Compare two copies of the agent-files set, AGENTS.md and\n\
        agent-data/, one line per file: same, differs, only in A, or\n\
        only in B. custom.md is reported as the project layer unless\n\
        -c/--custom compares it. A defaults to the config's\n\
        agent-files.diff.dir, else family.template, relative to the\n\
        config file's directory, and B to this workspace.\n\n\
        With one operand it is A, and B is this workspace: `diff ../x`\n\
        compares ../x against here. Give both to compare the other way,\n\
        or two copies from anywhere. Exits non-zero when anything\n\
        differs, as diff does."
    )]
    Diff(diff::DiffArgs),

    /// Make DST's set a copy of SRC's, uncommitted
    #[command(
        long_about = "Copy the set in SRC over the one in DST: AGENTS.md and\n\
        agent-data/, deletions included, never TODO.md, and custom.md\n\
        only with -c/--custom. SRC defaults to the config's\n\
        agent-files.copy.dir, else family.template, and DST to this\n\
        workspace.\n\n\
        With one operand it is SRC, and DST is this workspace: `copy\n\
        ../x` copies from ../x into here. Give both to send this\n\
        workspace's set somewhere, `copy . ../x`. Prints both ends and\n\
        each step, refuses a DST whose jj working copy already changes\n\
        the set, and leaves the result uncommitted for review."
    )]
    Copy(copy::CopyArgs),

    /// Count the set's lines, and slide the table that records them
    #[command(long_about = "Count the set's markdown, AGENTS.md, custom.md, and\n\
        agent-data/*.md, one line per file and a total. The version\n\
        marker is not markdown, so it takes no row and no place in\n\
        the file count. It is empty, so it would add nothing to the\n\
        total either.\n\
        agent-data/rationale.md is: its number is shown in angle\n\
        brackets and left out of the total, being the rules' why\n\
        rather than a rule.\n\n\
        Then the per-file table in notes/agent-files-size.md, the one\n\
        headed `| File |`, gets a new leftmost column labelled by the\n\
        set's version file and loses its rightmost one, so the window\n\
        keeps its width. Dry-run by default: --no-dry-run writes it.\n\
        DIR defaults to this workspace, --file names another notes\n\
        file, and --label names a column the version file cannot,\n\
        written --label=TEXT when the label opens on a `-`.")]
    Size(size::SizeArgs),
}

impl AgentFilesArgs {
    /// Run the chosen subcommand against the workspace found from
    /// the current directory.
    pub fn run(&self) -> ExitCode {
        match &self.command {
            AgentFilesCommand::Version => {
                let root = common::find_workspace_root();
                let vs = root.as_deref().map(versions).unwrap_or_default(); // OK: no root, no versions
                if vs.is_empty() {
                    error!("agent-files version: {}", report_line(root.as_deref()));
                    return ExitCode::FAILURE;
                }
                for v in vs {
                    println!("{v}");
                }
                ExitCode::SUCCESS
            }
            AgentFilesCommand::Diff(args) => args.run(),
            AgentFilesCommand::Copy(args) => args.run(),
            AgentFilesCommand::Size(args) => args.run(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

