179	    /// The validation's commands, the workspace's when it gives them,
180	    /// else the defaults.
181	    pub fn validation(&self, fast: bool) -> Vec<Vec<String>> {
182	        let (given, default) = match fast {
183	            true => (&self.validate_fast, FAST),
184	            false => (&self.validate, FULL),
