1	//! The workspace the tasks run in, as `cargo metadata` describes it:
2	//! its target directory, its binaries, which one is the default, and
3	//! the settings it gives xtask. Nothing here names a project, so
4	//! `xtask/` copies verbatim between workspaces.
5	//!
6	//! - The settings are `[workspace.metadata.xtask]` in the root
7	//!   `Cargo.toml`, every key optional:
8	//!   - `default-bin`: the binary a task takes when `--bin` names none.
9	//!   - `validate` and `validate-fast`: the validation's commands, each
10	//!     an array of words, `"cargo"` the cargo running the task, in
11	//!     place of [`FULL`] and [`FAST`].
12	//! - The default binary is `--bin`, else `default-bin`, else the root
13	//!   package's `default-run`, a `[package]` key a virtual workspace has
14	//!   no place for, else the one bin target, xtask's own left out, else
15	//!   none, refused naming them.
16	
17	use std::path::{Path, PathBuf};
18	
19	use crate::util::{cargo, command, profile_dir};
20	
21	/// The default full validation, each element one command.
22	pub const FULL: &[&[&str]] = &[
23	    &["cargo", "fmt"],
24	    &["cargo", "clippy", "--all-targets", "--", "-D", "warnings"],
25	    &["cargo", "test"],
26	];
27	
28	/// The default fast validation, the binaries' unit tests alone.
29	pub const FAST: &[&[&str]] = &[&["cargo", "test", "--bins"]];
30	
31	/// A bin target of a workspace member.
32	#[derive(Debug, Clone, PartialEq, Eq)]
33	pub struct Bin {
34	    /// The target's name, the binary's file name.
35	    pub name: String,
36	    /// Whether its package is a default member, built by a plain
37	    /// `cargo build`.
38	    pub default_member: bool,
39	}
40	
41	/// What the tasks know of the workspace.
42	#[derive(Debug, PartialEq, Eq)]
43	pub struct Workspace {
44	    /// Cargo's target directory.
45	    pub target_dir: PathBuf,
46	    /// The members' bin targets, xtask's own left out.
47	    pub bins: Vec<Bin>,
48	    /// `[workspace.metadata.xtask] default-bin`.
49	    pub default_bin: Option<String>,
50	    /// The root package's `default-run`, when the root is a package.
51	    pub default_run: Option<String>,
52	    /// `[workspace.metadata.xtask] validate`.
53	    pub validate: Option<Vec<Vec<String>>>,
54	    /// `[workspace.metadata.xtask] validate-fast`.
55	    pub validate_fast: Option<Vec<Vec<String>>>,
56	}
57	
58	impl Workspace {
59	    /// Read the workspace at `root` through `cargo metadata`.
60	    pub fn read(root: &Path) -> Result<Workspace, String> {
61	        let out = command(cargo())
62	            .current_dir(root)
63	            .args([
64	                "metadata",
65	                "--format-version",
66	                "1",
67	                "--no-deps",
68	                "--offline",
69	            ])
70	            .output()
71	            .map_err(|e| format!("cargo metadata did not run: {e}"))?;
72	        if !out.status.success() {
73	            return Err(format!(
74	                "cargo metadata failed: {}",
75	                String::from_utf8_lossy(&out.stderr).trim()
76	            ));
77	        }
78	        let meta: serde_json::Value = serde_json::from_slice(&out.stdout)
79	            .map_err(|e| format!("cargo metadata printed no JSON: {e}"))?;
80	        Workspace::from_metadata(&meta, env!("CARGO_PKG_NAME"))
81	    }
82	
83	    /// The workspace in `cargo metadata`'s JSON, the package named
84	    /// `own`, xtask's, left out of the binaries.
85	    pub fn from_metadata(meta: &serde_json::Value, own: &str) -> Result<Workspace, String> {
86	        let text = |v: &serde_json::Value| v.as_str().map(str::to_string);
87	        let target_dir = text(&meta["target_directory"])
88	            .map(PathBuf::from)
89	            .ok_or("cargo metadata named no target_directory")?;
90	        let root = text(&meta["workspace_root"]).ok_or("cargo metadata named no workspace_root")?;
91	        let root_manifest = Path::new(&root).join("Cargo.toml");
92	        let defaults: Vec<&str> = match meta["workspace_default_members"].as_array() {
93	            Some(ids) => ids.iter().filter_map(|id| id.as_str()).collect(),
94	            None => Vec::new(),
95	        };
96	        let mut bins = Vec::new();
97	        let mut default_run = None;
98	        for package in meta["packages"].as_array().into_iter().flatten() {
99	            // OK: a package with no manifest path is no root package
100	            if Path::new(package["manifest_path"].as_str().unwrap_or_default()) == root_manifest {
101	                default_run = text(&package["default_run"]);
102	            }
103	            if package["name"] == own {
104	                continue;
105	            }
106	            let default_member = package["id"]
107	                .as_str()
108	                .is_some_and(|id| defaults.contains(&id));
109	            for target in package["targets"].as_array().into_iter().flatten() {
110	                let is_bin = target["kind"]
111	                    .as_array()
112	                    .is_some_and(|kinds| kinds.iter().any(|k| k == "bin"));
113	                if let (true, Some(name)) = (is_bin, text(&target["name"])) {
114	                    bins.push(Bin {
115	                        name,
116	                        default_member,
117	                    });
118	                }
119	            }
120	        }
121	        let settings = &meta["metadata"]["xtask"];
122	        Ok(Workspace {
123	            target_dir,
124	            bins,
125	            default_bin: text(&settings["default-bin"]),
126	            default_run,
127	            validate: commands(&settings["validate"], "validate")?,
128	            validate_fast: commands(&settings["validate-fast"], "validate-fast")?,
129	        })
130	    }
131	
132	    /// The binary a task takes: `requested`, else the default, refused
133	    /// when there is none or it names no binary of the workspace.
134	    pub fn bin(&self, requested: Option<&str>) -> Result<&Bin, String> {
135	        let names = || {
136	            self.bins
137	                .iter()
138	                .map(|b| format!("`{}`", b.name))
139	                .collect::<Vec<_>>()
140	                .join(", ")
141	        };
142	        let find = |name: &str, from: &str| {
143	            self.bins.iter().find(|b| b.name == name).ok_or_else(|| {
144	                format!(
145	                    "{from} names `{name}`, not a binary of the workspace, whose are {}",
146	                    names()
147	                )
148	            })
149	        };
150	        if let Some(name) = requested {
151	            return find(name, "--bin");
152	        }
153	        if let Some(name) = &self.default_bin {
154	            return find(name, "[workspace.metadata.xtask] default-bin");
155	        }
156	        if let Some(name) = &self.default_run {
157	            return find(name, "the root package's default-run");
158	        }
159	        match self.bins.as_slice() {
160	            [one] => Ok(one),
161	            [] => Err("the workspace has no binary".to_string()),
162	            _ => Err(format!(
163	                "the workspace has binaries {}, and none is the default: pass --bin NAME, or name \
164	                 one in [workspace.metadata.xtask] default-bin",
165	                names()
166	            )),
167	        }
168	    }
169	
170	    /// Where the build of `profile` leaves `bin`.
171	    pub fn binary(&self, profile: &str, bin: &Bin) -> PathBuf {
172	        self.target_dir.join(profile_dir(profile)).join(format!(
173	            "{}{}",
174	            bin.name,
175	            std::env::consts::EXE_SUFFIX
176	        ))
177	    }
178	
179	    /// The validation's commands, the workspace's when it gives them,
180	    /// else the defaults.
181	    pub fn validation(&self, fast: bool) -> Vec<Vec<String>> {
182	        let (given, default) = match fast {
183	            true => (&self.validate_fast, FAST),
184	            false => (&self.validate, FULL),
185	        };
186	        match given {
187	            Some(lists) => lists.clone(),
188	            None => default
189	                .iter()
190	                .map(|words| words.iter().map(|w| w.to_string()).collect())
191	                .collect(),
192	        }
193	    }
194	}
195	
196	/// A list of commands in the settings, `key` naming it in an error:
197	/// absent is `None`, and anything but a non-empty array of non-empty
198	/// arrays of strings is refused.
199	fn commands(value: &serde_json::Value, key: &str) -> Result<Option<Vec<Vec<String>>>, String> {
200	    if value.is_null() {
201	        return Ok(None);
202	    }
203	    let bad = || {
204	        format!(
205	            "[workspace.metadata.xtask] {key} is not a list of commands, each an array of words, \
206	             such as [[\"cargo\", \"test\"]]"
207	        )
208	    };
209	    let lists = value.as_array().filter(|l| !l.is_empty()).ok_or_else(bad)?;
210	    lists
211	        .iter()
212	        .map(|words| {
213	            let words = words.as_array().filter(|w| !w.is_empty()).ok_or_else(bad)?;
214	            words
215	                .iter()
216	                .map(|w| w.as_str().map(str::to_string).ok_or_else(bad))
217	                .collect()
218	        })
219	        .collect::<Result<Vec<_>, _>>()
220	        .map(Some)
221	}
222	
223	#[cfg(test)]
224	mod tests {
225	    use super::*;
226	    use serde_json::json;
227	
228	    /// A package of a test workspace: its name, its bin targets, its
229	    /// `default-run`, and whether it is the root package.
230	    type Package<'a> = (&'a str, &'a [&'a str], Option<&'a str>, bool);
231	
232	    /// `cargo metadata`'s JSON for a workspace at `/w` of `packages`,
233	    /// each a name, its bin targets, its `default-run`, and whether
234	    /// it is the root package, every one a default member.
235	    fn meta(packages: &[Package], xtask: serde_json::Value) -> serde_json::Value {
236	        let packages: Vec<_> = packages
237	            .iter()
238	            .map(|(name, bins, default_run, root)| {
239	                let manifest = match root {
240	                    true => "/w/Cargo.toml".to_string(),
241	                    false => format!("/w/{name}/Cargo.toml"),
242	                };
243	                let mut targets: Vec<_> = bins
244	                    .iter()
245	                    .map(|b| json!({"name": b, "kind": ["bin"]}))
246	                    .collect();
247	                targets.push(json!({"name": name, "kind": ["lib"]}));
248	                json!({
249	                    "name": name,
250	                    "id": format!("id-{name}"),
251	                    "manifest_path": manifest,
252	                    "default_run": default_run,
253	                    "targets": targets,
254	                })
255	            })
256	            .collect();
257	        let defaults: Vec<_> = packages_defaults(&packages);
258	        json!({
259	            "target_directory": "/w/target",
260	            "workspace_root": "/w",
261	            "workspace_default_members": defaults,
262	            "packages": packages,
263	            "metadata": {"xtask": xtask},
264	        })
265	    }
266	
267	    /// Every package a default member, as a workspace with no
268	    /// `default-members` has it.
269	    fn packages_defaults(packages: &[serde_json::Value]) -> Vec<serde_json::Value> {
270	        packages.iter().map(|p| p["id"].clone()).collect()
271	    }
272	
273	    fn names(ws: &Workspace) -> Vec<&str> {
274	        ws.bins.iter().map(|b| b.name.as_str()).collect()
275	    }
276	
277	    /// The binaries are the members' bin targets, xtask's left out, and
278	    /// the default follows `--bin`, `default-bin`, `default-run`, then
279	    /// the one binary.
280	    #[test]
281	    fn the_default_binary_is_declared_or_the_only_one() {
282	        let one = Workspace::from_metadata(
283	            &meta(
284	                &[
285	                    ("app", &["app"], None, true),
286	                    ("xtask", &["xtask"], None, false),
287	                ],
288	                json!(null),
289	            ),
290	            "xtask",
291	        )
292	        .unwrap();
293	        assert_eq!(names(&one), ["app"]);
294	        assert_eq!(one.bin(None).unwrap().name, "app");
295	        assert_eq!(
296	            one.binary("dev", one.bin(None).unwrap()),
297	            PathBuf::from(format!(
298	                "/w/target/debug/app{}",
299	                std::env::consts::EXE_SUFFIX
300	            ))
301	        );
302	
303	        let two = |xtask: serde_json::Value, default_run: Option<&str>| {
304	            Workspace::from_metadata(
305	                &meta(
306	                    &[
307	                        ("root", &[], default_run, true),
308	                        ("a", &["a"], None, false),
309	                        ("b", &["b", "b2"], None, false),
310	                        ("xtask", &["xtask"], None, false),
311	                    ],
312	                    xtask,
313	                ),
314	                "xtask",
315	            )
316	            .unwrap()
317	        };
318	        let none = two(json!(null), None);
319	        assert_eq!(names(&none), ["a", "b", "b2"]);
320	        let e = none.bin(None).unwrap_err();
321	        assert!(
322	            e.contains("`a`, `b`, `b2`") && e.contains("--bin NAME"),
323	            "{e}"
324	        );
325	        assert_eq!(none.bin(Some("b2")).unwrap().name, "b2");
326	        let e = none.bin(Some("xtask")).unwrap_err();
327	        assert!(e.contains("not a binary of the workspace"), "{e}");
328	        assert_eq!(
329	            two(json!({"default-bin": "b"}), None)
330	                .bin(None)
331	                .unwrap()
332	                .name,
333	            "b"
334	        );
335	        assert_eq!(two(json!(null), Some("a")).bin(None).unwrap().name, "a");
336	        assert_eq!(
337	            two(json!({"default-bin": "b"}), Some("a"))
338	                .bin(None)
339	                .unwrap()
340	                .name,
341	            "b",
342	            "default-bin outranks default-run"
343	        );
344	        let e = two(json!({"default-bin": "c"}), None)
