1	//! `cargo xtask`: the workspace's own tasks, run by the alias in
2	//! `.cargo/config.toml`, naming nothing of the workspace, so `xtask/`
3	//! copies verbatim into any Rust workspace.
4	//!
5	//! - [`tasks`]: the tasks, one module each, and how to add one.
6	//! - [`util`], [`provenance`], and [`workspace`]: what the tasks share.
7	//!
8	//! This file parses the arguments and hands them to the task, and a
9	//! new task never changes it.
10	
11	use std::process::ExitCode;
12	
13	use clap::{CommandFactory, Parser};
14	use clap_complete::CompleteEnv;
15	
16	mod provenance;
17	mod tasks;
18	mod util;
19	mod workspace;
20	
21	use tasks::{Task, dispatch};
22	
23	/// The project's own tasks.
24	#[derive(Parser, Debug)]
25	#[command(name = "xtask", bin_name = "cargo xtask", max_term_width = 80)]
26	struct Cli {
27	    #[command(subcommand)]
28	    task: Task,
29	}
30	
31	fn main() -> ExitCode {
32	    // With `COMPLETE` set these answer a completion request and exit,
33	    // run's arguments by the binary it runs and the rest by clap.
34	    tasks::run::forward_completion(&util::root());
35	    CompleteEnv::with_factory(Cli::command).complete();
36	    match dispatch(&Cli::parse().task) {
37	        Ok(code) => code,
38	        Err(e) => {
39	            eprintln!("xtask: {e}");
40	            ExitCode::FAILURE
41	        }
42	    }
43	}
44	
