46	mod tests {
47	    use super::*;
48	
49	    /// The words the completion engine offers for `args`, the last of
50	    /// them the word being completed.
51	    fn completes(args: &[&str]) -> Vec<String> {
52	        let mut cmd = Cli::command();
53	        let words: Vec<std::ffi::OsString> = args.iter().map(Into::into).collect();
54	        clap_complete::engine::complete(&mut cmd, words, args.len() - 1, None)
55	            .expect("completes")
56	            .iter()
57	            .map(|c| c.get_value().to_string_lossy().into_owned())
58	            .collect()
59	    }
60	
61	    /// The tasks complete by name, whatever the command was typed as,
62	    /// `bump` offers its two words, and `--profile` the profiles.
63	    #[test]
64	    fn the_tasks_and_bumps_words_complete() {
65	        let tasks = completes(&["cx", ""]);
66	        for task in [
67	            "version",
68	            "bump",
69	            "completions",
70	            "validate",
71	            "build",
72	            "run",
73	            "install",
74	        ] {
75	            assert!(tasks.iter().any(|t| t == task), "{task}: {tasks:?}");
76	        }
77	        assert_eq!(completes(&["cargo-xtask", "ve"]), ["version"]);
78	        assert_eq!(completes(&["cx", "bump", ""])[..2], ["next", "bare"]);
79	        assert_eq!(completes(&["cx", "bump", "n"]), ["next"]);
80	        assert_eq!(
81	            completes(&["cx", "build", "--profile", ""])[..2],
82	            ["dev", "release"]
83	        );
84	    }
