86	    /// The arguments are clap's, `-h` is help, and each task's help is
87	    /// the one its `Args` carries.
88	    #[test]
89	    fn the_arguments_are_claps() {
90	        let parse = |args: &[&str]| Cli::try_parse_from(args).map(|c| c.task);
91	        assert!(matches!(parse(&["xtask", "version"]), Ok(Task::Version(_))));
92	        assert!(matches!(parse(&["xtask", "bump", "next"]), Ok(Task::Bump(a)) if a.to == "next"));
93	        let help = parse(&["xtask", "-h"]).unwrap_err();
94	        assert_eq!(help.kind(), clap::error::ErrorKind::DisplayHelp);
95	        let help = help.to_string();
96	        assert!(help.contains("cargo xtask"), "{help}");
97	        assert!(help.contains("Build a profile, dev by default"), "{help}");
98	        let help = parse(&["xtask", "help", "run"]).unwrap_err().to_string();
99	        assert!(help.contains("needs no `--`"), "{help}");
100	        assert!(parse(&["xtask", "bump"]).is_err(), "bump needs its word");
101	        assert!(parse(&["xtask"]).is_err(), "a task is required");
102	    }
