104	    /// `run` parses as `cargo run` does: its own flags first, and the
105	    /// binary's from the first word that is not one, a hyphen word
106	    /// included, with no `-h` of its own.
107	    #[test]
108	    fn run_takes_the_binarys_arguments_as_cargo_run_does() {
109	        let run = |args: &[&str]| match Cli::try_parse_from(args).unwrap().task {
110	            Task::Run(a) => (a.profile.name("dev"), a.args),
111	            other => panic!("expected run, got {other:?}"),
112	        };
113	        let words = |s: &str| s.split(' ').map(str::to_string).collect::<Vec<_>>();
114	        assert_eq!(
115	            run(&["xtask", "run", "st", "-sb"]),
116	            ("dev".into(), words("st -sb"))
117	        );
118	        assert_eq!(
119	            run(&["xtask", "run", "--release", "st", "-sb"]),
120	            ("release".into(), words("st -sb"))
121	        );
122	        assert_eq!(
123	            run(&["xtask", "run", "--profile", "soak", "st"]),
124	            ("soak".into(), words("st"))
125	        );
126	        assert_eq!(run(&["xtask", "run", "-V"]), ("dev".into(), words("-V")));
127	        assert_eq!(
128	            run(&["xtask", "run", "--help"]),
129	            ("dev".into(), words("--help"))
130	        );
131	        assert_eq!(run(&["xtask", "run", "-h"]), ("dev".into(), words("-h")));
132	        assert_eq!(
133	            run(&["xtask", "run", "--", "--release"]),
134	            ("dev".into(), words("--release"))
135	        );
136	        assert_eq!(
137	            run(&["xtask", "run", "st", "--release"]),
138	            ("dev".into(), words("st --release"))
139	        );
140	        assert_eq!(run(&["xtask", "run"]), ("dev".into(), vec![]));
141	        assert!(Cli::try_parse_from(["xtask", "run", "--release", "--profile", "x"]).is_err());
142	        match Cli::try_parse_from(["xtask", "run", "--bin", "tool", "st", "--bin"])
143	            .unwrap()
144	            .task
145	        {
146	            Task::Run(a) => {
147	                assert_eq!(a.bin.bin.as_deref(), Some("tool"));
148	                assert_eq!(a.args, ["st", "--bin"], "a later --bin is the binary's");
149	            }
