154	    /// Build and install take a profile, dev by default, and a binary.
155	    #[test]
156	    fn build_and_install_take_a_profile() {
157	        let parse = |args: &[&str]| Cli::try_parse_from(args).unwrap().task;
158	        match parse(&["xtask", "build"]) {
159	            Task::Build(a) => assert_eq!(a.profile.name("dev"), "dev"),
160	            other => panic!("{other:?}"),
161	        }
162	        match parse(&[
163	            "xtask",
164	            "install",
165	            "--profile",
166	            "dev",
167	            "--dry-run",
168	            "--dir",
169	            "d",
170	        ]) {
171	            Task::Install(a) => {
172	                assert_eq!(a.profile.name("dev"), "dev");
173	                assert_eq!(a.dir, Some(std::path::PathBuf::from("d")));
174	                assert!(a.dry_run);
175	            }
176	            other => panic!("{other:?}"),
177	        }
178	        match parse(&["xtask", "install"]) {
179	            Task::Install(a) => {
180	                assert_eq!(a.profile.name("dev"), "dev");
181	                assert_eq!(a.bin.bin, None);
182	            }
183	            other => panic!("{other:?}"),
184	        }
