1	//! `cargo xtask validate [--fast]`: check the source, each command of
2	//! the list one invocation, stopping at the first failure.
3	//!
4	//! - The lists are the workspace's, `[workspace.metadata.xtask]
5	//!   validate` and `validate-fast`, else the defaults in
6	//!   [`crate::workspace`]: `cargo fmt`, `cargo clippy --all-targets --
7	//!   -D warnings`, and `cargo test`, or `cargo test --bins` alone.
8	//! - The commands run with the build's provenance, as `build`'s do, so
9	//!   the test build compiles with the commit and state the dev build
10	//!   that follows it has, which then reuses it rather than recompiling.
11	
12	use std::process::ExitCode;
13	
14	use crate::provenance::Provenance;
15	use crate::util::{command_at, root, status};
16	use crate::workspace::Workspace;
17	
18	/// The task's arguments.
19	#[derive(clap::Args, Debug)]
20	#[command(
21	    about = "Check the source: fmt, clippy, and the tests, by default",
22	    long_about = "\
23	        Check the source, stopping at the first failure, by the workspace's\n\
24	        [workspace.metadata.xtask] validate list, or validate-fast with\n\
25	        --fast, each command an array of words, `cargo` the cargo running\n\
26	        the task. Without them, `cargo fmt`, `cargo clippy --all-targets --\n\
27	        -D warnings`, and `cargo test`, or `cargo test --bins` alone with\n\
28	        --fast. Each runs with the build's provenance, as build's does, so\n\
29	        the test build is the one a dev build then reuses."
30	)]
31	pub struct Args {
32	    /// Run the fast list, by default the binaries' unit tests alone
33	    #[arg(long)]
34	    pub fast: bool,
35	}
36	
37	/// Run the list in order, stopping at the first failure.
38	pub fn run(args: &Args) -> Result<ExitCode, String> {
39	    let name = match args.fast {
40	        true => "fast",
41	        false => "full",
42	    };
43	    let root = root();
44	    let lists = Workspace::read(&root)?.validation(args.fast);
45	    let provenance = Provenance::read(&root);
46	    for (i, words) in lists.iter().enumerate() {
